{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C48"],
      "claim": "Tolbutamide, a p-toluenesulfonylurea sharing the same sulfonylurea core as the query, has a human absolute oral bioavailability of 80–90%, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Glimepiride, another sulfonylurea antidiabetic, is essentially completely bioavailable (97% absolute) after oral tablet dosing, indicating that the sulfonylurea class is generally well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Even the more polar, zwitterionic sulfonamide sulpiride has an absolute oral bioavailability of about 28%, above the 20% threshold, showing that ionized/polar sulfonamide-containing molecules can still meet the threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a sulfonylurea (gliclazide-like) molecule. Close structural analogues tolbutamide and glimepiride show absolute oral bioavailability of 80–100%, and even the more polar sulpiride reaches ~28%, above the 20% threshold. The physicochemical prior suggesting low permeability is outweighed by direct experimental evidence from the same drug class.",
  "evidence_gaps": [
    "No direct absolute bioavailability record for the exact query molecule (gliclazide-like) was provided; extrapolation relies on close sulfonylurea analogues.",
    "First-pass metabolism and transporter-mediated effects for the query were not directly measured in the provided evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

